package com.procurement.approvaltask.mapper; import com.procurement.approvaltask.dto.response.*;import com.procurement.approvaltask.entity.*;import org.springframework.stereotype.Component;@Component public class ApprovalTaskMapper{public ApprovalTaskResponse toResponse(ApprovalTask e){return new ApprovalTaskResponse(e.getId(),e.getTaskNumber(),e.getPurchaseRequest().getId(),e.getPurchaseRequest().getRequestNumber(),e.getApprovalStage().getId(),e.getApprovalStage().getStageName(),e.getAssignedEmployee().getId(),e.getAssignedEmployee().getFirstName()+" "+e.getAssignedEmployee().getLastName(),e.getAssignedRole().getId(),e.getAssignedRole().getRoleName(),e.getStatus(),e.getComments(),e.getAssignedDate(),e.getCompletedDate(),e.getApprovedAmount(),e.getCreatedAt(),e.getUpdatedAt());}}
